export const mediaInspectionBefore = {
  "src/svelte/views/MediaContent.svelte": "<script lang=\"ts\">\n  import { setContext } from \"svelte\";\n  import type { MediaLibrary } from \"../../views/media-library.ts\";\n  import CatalogHome from \"../explorer/CatalogHome.svelte\";\n  import Viewer from \"../pieces/media/Viewer.svelte\";\n  import { catalogPhotos, type Photo } from \"../pieces/media/source.ts\";\n  import { mediaContent, mediaImages, mediaTarget, mediaAlbum } from \"./media-data.ts\";\n  let { library, album, onalbum }: {\n    library: MediaLibrary; album: string | null; onalbum: (id: string) => void;\n  } = $props();\n  let owner: HTMLDivElement;\n  let open = $state(false), index = $state(0), title = $state(\"\");\n  let photos = $state.raw<readonly Photo[]>([]);\n  let opener: HTMLElement | null = null;\n  setContext(\"catalog-photo-intent\", (record: string) => {\n    const target = mediaTarget(library, record);\n    return target?.kind === \"image\" ? target.image.image.asset\n      : target ? library.images.find(image => image.id === target.album.cover)?.image.asset : undefined;\n  });\n  export function select(record: string) {\n    const target = mediaTarget(library, record);\n    if (!target) return false;\n    if (target.kind === \"album\") { onalbum(target.album.id); return true; }\n    const current = mediaImages(library, album);\n    // A result outside the current album opens the library queue, not a wrong index.\n    const inAlbum = current.some(image => image.id === target.image.id);\n    const queue = inAlbum ? current : library.images;\n    index = queue.findIndex(image => image.id === target.image.id);\n    photos = catalogPhotos(queue.map(image => image.image));\n    title = inAlbum ? mediaAlbum(library, album)?.title ?? \"Media\" : \"Media\";\n    opener = owner.querySelector<HTMLElement>(`[data-record=\"${CSS.escape(record)}\"] button`);\n    open = true;\n    return true;\n  }\n  function returnFocus() {\n    const target = opener?.isConnected && opener.checkVisibility() ? opener\n      : owner.closest<HTMLElement>(\"[data-catalog-scroll]\");\n    target?.focus({ preventScroll: true });\n  }\n</script>\n\n<div bind:this={owner} data-media-library={library.id} data-media-album={album ?? undefined}>\n  <CatalogHome node={mediaContent(library, album)} bodyOnly\n    onevent={event => { if (event.kind === \"catalog.open\") select(event.record); }} />\n  {#if open}<Viewer {photos} {title} bind:index bind:open onreturn={returnFocus} />{/if}\n</div>\n",
  "src/svelte/views/InspectionContent.svelte": "<script lang=\"ts\">\n  import { tick } from \"svelte\";\n  import type { BankEvent } from \"../../interaction/bank-events.ts\";\n  import type { PrimitiveId } from \"../../interaction/catalog.ts\";\n  import type { PublicBankInput } from \"../explorer/PublicCatalogBank-model.ts\";\n  import PublicCatalogBank from \"../explorer/PublicCatalogBank.svelte\";\n  import RetainedPlace from \"../explorer/RetainedPlace.svelte\";\n  import BankRenderer from \"../BankRenderer.svelte\";\n  import Toolbar from \"../pieces/Toolbar.svelte\";\n  import { inspectionCatalog } from \"../catalog/inspection-fixture.ts\";\n\n  let { catalog = inspectionCatalog }: {\n    catalog?: PublicBankInput;\n  } = $props();\n  let bank: PublicCatalogBank | undefined = $state();\n  let selected = $state<string | null>(null);\n  let detail = $derived(catalog.details.find(item => item.record === selected));\n  let opener: HTMLElement | null = null;\n  async function back() {\n    selected = null;\n    await tick();\n    if (opener?.isConnected) opener.focus({ preventScroll: true });\n  }\n  function interact(event: BankEvent) {\n    if (event.kind === \"catalog.open\") {\n      if (!catalog.details.some(item => item.record === event.record)) throw new Error(\"UNKNOWN_INSPECTION_RECORD\");\n      opener = document.activeElement instanceof HTMLElement ? document.activeElement : null;\n      selected = event.record;\n    } else if (event.kind === \"catalog.back\") void back();\n  }\n  export async function revealEntry(id: PrimitiveId): Promise<HTMLElement | null> {\n    selected = null;\n    await tick();\n    return bank?.revealEntry(id) ?? null;\n  }\n</script>\n\n<RetainedPlace active={!detail}>\n  <PublicCatalogBank bind:this={bank} surface={catalog} oncatalog={interact} bodyOnly />\n</RetainedPlace>\n{#if detail}\n  <Toolbar toolbar={{ edge: \"top\", title: detail.title, subtitle: \"Local renderer example\", leading: {\n    intent: { kind: \"back\" }, icon: \"back\", label: \"Back to visual catalog\", state: \"ready\",\n  } }} invoke={() => void back()} />\n  <BankRenderer node={detail} onevent={interact} />\n{/if}\n",
  "src/svelte/explorer/PublicCatalogBank.svelte": "<script lang=\"ts\">\n  import { tick } from \"svelte\";\n  import type { BankEvent } from \"../../interaction/bank-events.ts\";\n  import type { PrimitiveId } from \"../../interaction/catalog.ts\";\n  import { catalogGroups } from \"../catalog/navigation.ts\";\n  import { InteractionCatalog } from \"../../interaction/catalog.ts\";\n  import CatalogNavigation from \"../catalog/CatalogNavigation.svelte\";\n  import CatalogGroupHeader from \"../catalog/CatalogGroupHeader.svelte\";\n  import CatalogFoundations from \"../catalog/CatalogFoundations.svelte\";\n  import ControlBench from \"../catalog/ControlBench.svelte\";\n  import SpecimenGroup from \"../catalog/SpecimenGroup.svelte\";\n  import SpecimenRow from \"../catalog/SpecimenRow.svelte\";\n  import SpecimenUnavailable from \"../catalog/SpecimenUnavailable.svelte\";\n  import PublicCatalogBankSpecimen from \"./PublicCatalogBankSpecimen.svelte\";\n  import { publicCatalogBankInventory, type PublicBankInput } from \"./PublicCatalogBank-model.ts\";\n  import PlaceHeader from \"../pieces/PlaceHeader.svelte\";\n  let { surface, oncatalog, bodyOnly = false }: {\n    surface: PublicBankInput; oncatalog: (event: BankEvent) => void; bodyOnly?: boolean;\n  } = $props();\n  let inventory = $derived(publicCatalogBankInventory(surface));\n  const entries = InteractionCatalog.entries;\n  export async function revealEntry(id: PrimitiveId): Promise<HTMLElement | null> {\n    await tick();\n    return document.querySelector<HTMLElement>(`[data-public-catalog-bank] [data-catalog-entry=\"${id}\"]`);\n  }\n</script>\n\n<section data-public-catalog-bank class=\"flex w-full min-w-0 max-w-[52rem] flex-col gap-8\" aria-label=\"Component bank\">\n  {#if !bodyOnly}\n  <PlaceHeader title=\"Component bank\" subtitle=\"Interactive examples. Changes stay here; no product commands are executed.\" />\n  {/if}\n  <CatalogNavigation {entries} />\n  {#each catalogGroups as group (group.id)}\n    <section class=\"flex min-w-0 flex-col gap-8\" aria-label={group.title}>\n    <CatalogGroupHeader family={group.family} />\n    {#if group.id === \"foundations\"}<CatalogFoundations />{/if}\n    {#each group.entries.filter(entry => entry.family !== \"control\") as entry (entry.id)}\n    <SpecimenGroup id={entry.id}>\n      {#each inventory.filter(item => item.id === entry.id) as specimen (specimen.state)}\n        <SpecimenRow id={entry.id} state={specimen.state} coverage={specimen.gap ? \"gap\" : \"rendered\"}>\n          {#if specimen.node}<PublicCatalogBankSpecimen initial={specimen.node} {oncatalog} />\n          {:else if specimen.gap}<SpecimenUnavailable reason={specimen.gap} />{/if}\n        </SpecimenRow>\n      {/each}\n    </SpecimenGroup>\n    {/each}\n    <ControlBench entryIds={group.entries.filter(entry => entry.family === \"control\").map(entry => entry.id)} />\n    </section>\n  {/each}\n</section>\n"
} as const;
